-- GenDB engine variant Q08-commuted_comparisons: template q08.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  o_year,
  SUM(CASE WHEN $1 = nation THEN volume ELSE 0 END) / SUM(volume) AS mkt_share
FROM (
  SELECT
    EXTRACT(YEAR FROM o_orderdate) AS o_year,
    l_extendedprice * (
      1 - l_discount
    ) AS volume,
    n2.n_name AS nation
  FROM part, supplier, lineitem, orders, customer, nation AS n1, nation AS n2, region
  WHERE
    l_partkey = p_partkey
    AND l_suppkey = s_suppkey
    AND o_orderkey = l_orderkey
    AND c_custkey = o_custkey
    AND n1.n_nationkey = c_nationkey
    AND r_regionkey = n1.n_regionkey
    AND $2 = r_name
    AND n2.n_nationkey = s_nationkey
    AND o_orderdate BETWEEN CAST('1995-01-01' AS DATE) AND CAST('1996-12-31' AS DATE)
    AND $3 = p_type
) AS all_nations
GROUP BY
  o_year
ORDER BY
  o_year
